import Phaser from 'phaser';

/** Layered pixel art for Chapter 1 (generated by tools/generate-hall-art.mjs). */
export const HALL_TEXTURES = [
  'cor-main',
  'cor-glow',
  'hall-back',
  'hall-glow',
  'hall-front',
  'hall-niche-lit',
  'hall-pedestal-lit',
  'hall-relief-door-slab',
  'hall-relief-door-passage',
  'hall-balance-door-slab',
  'hall-balance-door-passage',
  'rel-bg',
  'rel-frame',
  'rel-glow',
  'rel-tiles',
  'rel-mini',
  'rel-picture',
  'rel-reference',
  'rel-reference-large',
  'bal-bg',
  'bal-lamps',
  'bal-glow',
  'bal-post',
  'bal-beam',
  'bal-pan',
  'bal-vessel',
  'bal-lever',
  'bal-lever-base',
  'bal-shelf',
  'bal-tablet',
  'bal-w-scarab',
  'bal-w-falcon',
  'bal-w-lotus',
  'bal-s-scarab',
  'bal-s-falcon',
  'bal-s-lotus',
  'bal-s-vessel',
] as const;

export type HallTexture = (typeof HALL_TEXTURES)[number];

export function hallAssetUrl(name: string) {
  return `${import.meta.env.BASE_URL}assets/hall/${name}.png`;
}

export function preloadHall(
  scene: Phaser.Scene,
  names: readonly HallTexture[] = HALL_TEXTURES,
) {
  for (const name of names)
    if (!scene.textures.exists(name))
      scene.load.image(name, hallAssetUrl(name));
  if (!scene.textures.exists('px')) {
    const g = scene.make.graphics({ x: 0, y: 0 }, false);
    g.fillStyle(0xffffff, 1);
    g.fillRect(0, 0, 1, 1);
    g.generateTexture('px', 1, 1);
    g.destroy();
  }
  scene.load.once(Phaser.Loader.Events.COMPLETE, () => crispenHall(scene));
}

/** Nearest-neighbour filtering keeps the authored pixels crisp. */
export function crispenHall(scene: Phaser.Scene) {
  for (const name of [...HALL_TEXTURES, 'px'])
    if (scene.textures.exists(name))
      scene.textures.get(name).setFilter(Phaser.Textures.FilterMode.NEAREST);
}
